import React from "react";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { DateCalendar } from "@mui/x-date-pickers/DateCalendar";

export default function CalanderModel({
  closeModel,
  time,
  setTime,
  date,
  setDate,
}) {
  const handleInputChange = (event) => {
    const { name, value } = event?.target;

    if (name == "hour" && value > 24) {
      return;
    }
    if (name == "minute" && value > 59) {
      return;
    }

    setTime((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  const handleBackgroundClick = (e) => {
    if (e?.target?.classList.contains("calander_model")) {
      closeModel();
    }
  };
  return (
    <div className="calander_model model" onClick={handleBackgroundClick}>
      <div className="calander_model__content">
        <LocalizationProvider
          dateAdapter={AdapterDayjs}
          className="calander_model__content__calander"
        >
          <DateCalendar
            value={date}
            onChange={(newValue) => setDate(newValue)}
          />
        </LocalizationProvider>

        <div className="calander_model__content__select_time">
          <span>Select Time:</span>
          <input
            type="text"
            className="calander_model__content__select_time__hour"
            maxLength="2"
            value={time?.hour}
            name="hour"
            onChange={handleInputChange}
          />
          :
          <input
            type="text"
            className="calander_model__content__select_time__minute"
            maxLength="2"
            value={time?.minute}
            name="minute"
            onChange={handleInputChange}
          />
          <select
            onChange={handleInputChange}
            value={time?.meridian}
            name="meridian"
            id="meridian"
            className="calander_model__content__select_time__minute"
          >
            <option value="am">AM</option>
            <option value="pm">PM</option>
          </select>
        </div>

        <button className="button-red" onClick={closeModel}>
          Schedule
        </button>
      </div>
    </div>
  );
}
