import React, { useEffect, useRef, useState } from "react";
import CalanderModel from "../../shared/Models/CalanderModel";
import http, { uploadImage } from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";
import FileUploadIcon from "@mui/icons-material/FileUpload";

export default function Notification() {
  const dispatch = useDispatch();
  const newNotificationRef = useRef(null);

  const [notificationListItems, setNotificationListItems] = useState([]);
  const [formData, setFormData] = useState({
    title: "",
    body: "",
    image: null,
    type: "",
  });
  const [calander, setCalander] = useState(false);
  const [navigationLink, setNavigationLink] = useState("");
  const [time, setTime] = useState({
    hour: "00",
    minute: "00",
    meridian: "am",
  });
  const [date, setDate] = useState(null);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.getNotification)
      .then(async (res) => {
        // console.log(res?.data);
        var data = res?.data?.notifications;

        for (let i = 0; i < data.length; i++) {
          data[i]["date"] = data[i]?.date?.split("T")[0];
        }

        setNotificationListItems(data);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const handleCloseModel = () => {
    let datee = new Date(date);
    var formattedDate =
      (datee.getDate() < 10 ? "0" : "") +
      datee.getDate() +
      "-" +
      (datee.getMonth() + 1 < 10 ? "0" : "") +
      (datee.getMonth() + 1) +
      "-" +
      datee.getFullYear();

    let form = { ...formData };
    form["date"] = formattedDate;
    setFormData(form);
    setCalander(false);
  };

  const handleInputChange = (el) => {
    let { name, value } = el?.target;
    setFormData((prev) => {
      return { ...prev, [name]: value };
    });
  };

  const handleImageChange = (el, value) => {
    let { name } = el?.target;
    setFormData((prev) => {
      return { ...prev, [name]: value };
    });
  };

  const uploadData = async () => {
    let form = { ...formData };
    console.log(form);
    let apiPath;

    if (formData?.type == "Default") {
      form["link"] = navigationLink;
      form["time"] = `${time.hour}:${time.minute} ${time.meridian}`;
      form["date"] = date;

      apiPath = apisPath?.admin?.getNotification;
    } else {
      apiPath = apisPath?.admin?.notification;
    }

    await http
      .post(apiPath, form, {
        headers: {
          "Content-Type": "application/json",
        },
      })
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
        setFormData({
          title: "",
          body: "",
          image: null,
          type: "",
        });
        setDate(null);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.getNotification}/${index}`)
      .then(async (res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <>
      <div className="notification">
        <h3 className="notification__heading page_heading">Notification</h3>
        <div className="notification__content">
          <div className="notification__content__notification_content">
            <div
              className="categories__content__new_brand__upload_logo"
              onClick={() => newNotificationRef?.current?.click()}
            >
              {!formData?.image ? (
                <>
                  <FileUploadIcon />
                  <span>Upload Notification Image</span>
                </>
              ) : (
                <img src={formData?.image} />
              )}
            </div>
            <input
              type="file"
              style={{ display: "none" }}
              ref={newNotificationRef}
              name="image"
              onChange={async (e) => {
                await uploadImage(e)
                  .then((res) => {
                    handleImageChange(e, res?.url);
                  })
                  .catch((err) => {
                    console.log(err);
                  });
              }}
            />
            <div>
              <label htmlFor="title">Title</label>
              <input
                type="text"
                id="title"
                name="title"
                value={formData?.title}
                placeholder="Enter here"
                onChange={handleInputChange}
              />
            </div>
            <div>
              <label htmlFor="notification_content">Notification content</label>
              <textarea
                name="body"
                cols="100"
                rows="10"
                placeholder="Enter here"
                id="notification_content"
                value={formData?.body}
                onChange={handleInputChange}
              ></textarea>
            </div>
          </div>

          <div className="notification__content__radio_button">
            <div className="notification__content__radio_button__container">
              <input
                type="checkbox"
                name="push_notification"
                id="push_notification"
                onClick={() =>
                  setFormData((prev) => {
                    return { ...prev, type: "Push" };
                  })
                }
                checked={formData?.type === "Push" ? true : false}
              />
              <label htmlFor="push_notification">Push notification</label>
            </div>
            <div className="notification__content__radio_button__container">
              <input
                type="checkbox"
                name="default_notification"
                id="default_notification"
                onClick={() =>
                  setFormData((prev) => {
                    return { ...prev, type: "Default" };
                  })
                }
                checked={formData?.type === "Default" ? true : false}
              />
              <label htmlFor="default_notification">Default notification</label>
            </div>
          </div>

          {formData?.type === "Default" && (
            <div>
              <label htmlFor="title">Navigation Link</label>
              <input
                type="text"
                id="title"
                name="title"
                value={navigationLink}
                placeholder="Enter here"
                onChange={(el) => setNavigationLink(el?.target?.value)}
              />
            </div>
          )}

          <div className="notification__content__buttons">
            <button className="button-red" onClick={uploadData}>
              Send notification
            </button>
            {formData?.type === "Default" && (
              <button
                className="button-border-red"
                onClick={() => {
                  setCalander(true);
                }}
              >
                Schedule
              </button>
            )}
          </div>

          <div className="notification__content__notification_list">
            <h4 className="notification__heading page_subheading">
              Notification list
            </h4>
            <div className="notification__content__notification_list__content">
              {notificationListItems?.length > 0 ? (
                notificationListItems?.map((item, index) => {
                  return (
                    <NotificationList
                      data={item}
                      key={index}
                      deleteData={() => deleteData(item?.id)}
                    />
                  );
                })
              ) : (
                <div className="no_data_found">No Data Found</div>
              )}
            </div>
          </div>
        </div>
      </div>

      {calander && (
        <CalanderModel
          closeModel={handleCloseModel}
          time={time}
          setTime={setTime}
          date={date}
          setDate={setDate}
        />
      )}
    </>
  );
}

const NotificationList = ({ data, deleteData }) => {
  return (
    <div className="notification_card">
      <div className="notification_card__notification_container">
        <img src={data?.image} alt="image" />
        <h3>{data?.title}</h3>
        <p>
          {data?.body?.substring(0, 50)}
          {data?.body?.length > 50 && "..."}
        </p>
        <span>
          <b>Schedule at:</b> {data?.date} {data?.time}
        </span>
      </div>
      <button className="button-red" onClick={deleteData}>
        Delete
      </button>
    </div>
  );
};
